// Turns the household JSON into an ES module so the browser worker and Node
// load it the same way. Usage: node scripts/import-households.mjs <json>
import fs from 'node:fs';
const src = process.argv[2] || 'data/households.json';
const data = JSON.parse(fs.readFileSync(src, 'utf8'));
fs.mkdirSync('data', { recursive: true });
if (src !== 'data/households.json') fs.writeFileSync('data/households.json', JSON.stringify(data, null, 2));
fs.writeFileSync('src/world/households.data.js',
  '// Generated by scripts/import-households.mjs from data/households.json. Do not edit.\n'
  + `export default ${JSON.stringify(data)};\n`);
console.log(`${data.households.length} households`);
